# "files" is computed by build.py. installed_by_plugin = loaded/used by Claude Code after `/plugin install ecc@ecc`.
# activation: event (hook, runs by itself) | model (Claude decides) | user (slash command / manual run) | none (data/docs).

def T(path, purpose, kind, auto, plugin, activation, language=None, note=None):
    d = {"path": path, "purpose": purpose, "kind": kind, "auto": auto, "installed_by_plugin": plugin,
         "activation": activation}
    if language:
        d["language"] = language
    if note:
        d["note"] = note
    return d


